<?php $company = App\Models\Company::create(["name" => "Test Co 500", "status" => "active", "plan_id" => 1, "company_code" => "TEST500"]); $user = App\Models\User::first(); $request = Illuminate\Http\Request::create("/api/v1/devices", "POST", ["customer_id" => 1, "emi_account_id" => null, "display_name" => "500 Test", "brand" => "Samsung", "model" => "", "manufacturer" => "Samsung"]); $request->headers->set("X-Company-Id", $company->id); $request->headers->set("Accept", "application/json"); Laravel\Sanctum\Sanctum::actingAs($user, ["*"]); $response = app(Illuminate\Contracts\Http\Kernel::class)->handle($request); echo $response->getStatusCode() . "\n" . $response->getContent();
